class DatRetencionPersona extends BaseDatRetencionPersona {

	/**
     * Obtener un listado de los datos de las retenciones de una persona.
     * 
	 * @param int $idpersona    Identificador de la persona.
	 * @param int $identidad    Identificador de la entidad.
     * @param int $inicio       Inicio de la busqueda.
     * @param int $limite       Limite maximo de la busqueda.
     * @return array    Listado de los datos de las retenciones de una persona.
     */
    //Devolviendo los datos de la persona en el listado de retenciones en forma de arreglo.
    public static function obtenerListadoRetencionesByIdpersonaEntidad($idpersona, $identidad, $inicio = 0, $limite = 15) {

        //Devolviendo el listado de las retenciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
                ->select('rp.*,
                    tr.denominacion as tiporetencion, tr.saldolimite as saldolimite, tr.cobrosypagos as cobrosypagos, tr.orden')
                ->from('DatRetencionPersona rp')
                ->leftjoin('rp.NomTipoRetencion tr')
				->where('rp.idpersona = ? and rp.identidad = ?', array($idpersona, $identidad))
				->orderBy('tr.orden ASC')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray();
    }

    public static function obtenerListadoRetencionesSinComprobante($identidad) {

        //Devolviendo el listado de las retenciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
            ->select('rp.*, tr.*')
            ->from('DatRetencionPersona rp')
            ->leftjoin('rp.NomTipoRetencion tr')
            ->where('rp.identidad = ? and rp.idcomprobante is null and tr.cobrosypagos = 1', array($identidad))
            ->fetchArray();
    }

    public static function obtenerRetencionesEntidad($identidad) {

        //Devolviendo el listado de las retenciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
            ->select('dr.*, tr.saldolimite')
            ->from('DatRetencionPersona dr')
            ->leftjoin('dr.NomTipoRetencion tr')
            ->where('dr.identidad = ?', array($identidad))
            ->fetchArray();
    }

    public static function obtenerCantRetencionesSinComprobante($identidad) {

        //Devolviendo el listado de las retenciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
            ->select('sum(rp.saldoinicial) as total')
            ->from('DatRetencionPersona rp')
            ->leftjoin('rp.NomTipoRetencion tr')
            ->where('rp.identidad = ? and rp.idcomprobante is null and tr.cobrosypagos = 1', array($identidad))
            ->fetchOne()
            ->total;
    }

  /**
   * Obtener un listado de los datos de las retenciones de una persona.
   *
   * @param int $idpersona    Identificador de la persona.
   * @param int $identidad    Identificador de la entidad.
   * @param int $inicio       Inicio de la busqueda.
   * @param int $limite       Limite maximo de la busqueda.
   * @return array    Listado de los datos de las retenciones de una persona.
   */
  public static function obtenerListadoAexportarRetencionesByIdpersonaEntidad($idpersona,
                                                                            $identidad) {

    //Devolviendo el listado de las retenciones de una persona en forma de arreglo.
    $result= Doctrine_Query::create()
      ->select('rp.*,
                    tr.denominacion as tiporetencion, tr.saldolimite as saldolimite')
      ->from('DatRetencionPersona rp')
      ->leftjoin('rp.NomTipoRetencion tr')
      ->where('rp.idpersona = ? and rp.identidad = ?', array($idpersona, $identidad))
      ->orderBy('rp.fechafin, rp.prioridad')
      ->fetchArray();

    return $result;
  }
	
	/**
     * Obtener la cantidad total de retenciones de una persona.
     * 
     * @return int      Cantidad total de retenciones de una persona.
     */
    public static function obtenerCantidadTotalRetencionesPersona($idpersona, $identidad) {

        //Devolviendo la cantidad total de retenciones de una persona.
        return Doctrine_Query::create()->select('COUNT(idretencionpersona) AS cantidad')
                        ->from('DatRetencionPersona')
						->where('idpersona = ? and identidad = ?', array($idpersona, $identidad))
                        ->fetchOne()
                        ->cantidad;
    }
	
