    public function obtenerReterncionesPersonasEntidad($identidad, $arrPersonas){
		$sql = "select rp.*, tr.saldolimite, dco.idcargosocupados, tr.denominacion as tiporetencion, tr.orden, nfe.ordenunico, 
                    replace (concat(trim(dp.nombre), ' ', trim(dp.snombre), ' ', trim(dp.papel), ' ', trim(dp.sapel)), ' ', ' ') as nombreyapellidos
					from mod_nomina.dat_retencionpersona rp
					left join mod_nomina.nom_tiporetencion tr on (tr.idtiporetencion = rp.idtiporetencion)
					left join mod_nomina.dat_cargosocupados dco on (dco.idpersona = rp.idpersona and dco.fechaaplicacion <= now() and (dco.fechavencimiento is null or dco.fechavencimiento >= now()) )       
                    inner join mod_persona.dat_persona dp on (dp.idpersona = dco.idpersona)                    
                    LEFT JOIN mod_estructuracomp.nom_filaestruc nfe on (nfe.idfila = dco.idcargo)
					where rp.identidad = $identidad and (rp.fechafin is null or rp.fechafin >= now()) and rp.idpersona in (".implode(',', $arrPersonas).")  and rp.activo = 1
					order by nfe.ordenunico ASC, tr.orden ASC;";
		$mg = Doctrine_Manager::getInstance();
		$conn = $mg->getCurrentConnection();
		$result = $conn->fetchAll($sql);
        return $result;
	}

    public function obtenerListadoPersonasRetencionesSinCuenta($identidad){
        $sql = "select dp.nombre, dp.snombre, dp.papel, dp.sapel, tr.denominacion 
					from mod_nomina.dat_retencionpersona rp
					left join mod_nomina.nom_tiporetencion tr on (tr.idtiporetencion = rp.idtiporetencion)
					inner join mod_persona.dat_persona dp on (dp.idpersona = rp.idpersona)
					where rp.identidad = ? and tr.cobrosypagos <> 1;";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        return $conn->fetchAll($sql, array($identidad));
    }

    public static function obtenerRetencionesDadoIdDocObligacionCobrosyPagos($iddocumentoobligacion) {

        //Devolviendo el listado de las retenciones de una persona en forma de arreglo.
        return Doctrine_Query::create()
            ->select('*')
            ->from('DatRetencionPersona')
            ->where('iddocumentoobligacion = ?', array($iddocumentoobligacion))
            ->fetchArray();
    }

    public static function obtenerListadoRetencionesPersona($identidad){
        $sql = "SELECT cpr.*, nfe.ordenunico,
                replace (concat(trim(dp.nombre), ' ', trim(dp.snombre), ' ', trim(dp.papel), ' ', trim(dp.sapel)), '  ', ' ') as nombreyapellidos
            FROM mod_nomina.conf_personaretencion cpr
                inner join mod_persona.dat_persona dp on (dp.idpersona = cpr.idpersona)
                INNER JOIN mod_nomina.dat_cargosocupados dco  on (dco.idpersona = cpr.idpersona)
                LEFT JOIN mod_estructuracomp.dat_cargo dc on (dc.idcargo = dco.idcargo)
                LEFT JOIN mod_estructuracomp.nom_filaestruc nfe on (nfe.idfila = dc.idcargo)
                LEFT JOIN mod_estructuracomp.nom_cargo nc on (nc.idnomcargo = dc.idnomcargo)
            WHERE cpr.identidad = ? ORDER BY nfe.ordenunico ASC;";
        $mg = Doctrine_Manager::getInstance();
        $conn = $mg->getCurrentConnection();
        $result = $conn->fetchAll($sql, array($identidad));
        return  $result;       
    }
}
